'use strict';
// Support links and the "More free viewers" list. Generated by mon1-work/gen.py from funding.json and the
// product list; edit those and run it again instead of editing this file by hand.
// Static text that ships in the package. No network call and no telemetry: the only outbound actions are the
// Sponsors page or a GitHub page opened by the user's own click, and an install the user picked in a QuickPick.
// The pure parts (fundingLinks, otherProducts, pickItems, footerHtml) need no VS Code, so tests can call them.

// A link shows only when its value is set. Never add a URL here that is not in funding.json.
const FUNDING = {
  "github_sponsors": "https://github.com/sponsors/theluckystrike",
  "paypal_me": "",
  "buy_me_a_coffee": ""
};

const FUNDING_LABELS = {
  github_sponsors: 'GitHub Sponsors',
  paypal_me: 'PayPal',
  buy_me_a_coffee: 'Buy Me a Coffee',
};

